package com.stocksense.inventory.stock; import com.stocksense.product.Product; import com.stocksense.warehouse.Location; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; @Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"product_id","location_id"})) @Getter @Setter @NoArgsConstructor public class StockBalance { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Product product; @ManyToOne(optional=false) private Location location; @Column(nullable=false,precision=19,scale=3) private BigDecimal quantityOnHand=BigDecimal.ZERO; @Version private Long version; }
